import {scenarioResultMessage} from './scenario-result-message.js?v=recent-construction-1';
import {createScenario} from './scenario-setup.js?v=recent-construction-1';
import {scenarioPreviewPanel,installScenarioPreview} from './scenario-preview.js?v=recent-construction-1';
import {scenarioProgramReport} from './scenario-program-report.js?v=recent-construction-1';
import {backgroundRulesReport} from './scenario-background-rules.js?v=recent-construction-1';
import {scenarioRanksReport} from './scenario-ranks.js?v=recent-construction-1';
import {escapeAnnouncement} from './scenario-announcements.js?v=recent-construction-1';
import {scenarioSpeedReport,resumeScenarioSpeed} from './scenario-speed.js?v=recent-construction-1';
import {scenarioStory} from './scenario-story.js?v=recent-construction-1';
import {scenarioEventReport,scenarioEnding} from './scenario-events.js?v=recent-construction-1';
import {showCustomScenarioEditor} from './scenario-editor.js?v=recent-construction-1';
import {SCENARIOS,scenarioGoals,scenarioDefinition} from './scenarios.js?v=recent-construction-1';
export function showScenarios(ui){const {city,dialog,close,start,exportCity,review,update,save}=ui,c=city(),s=c.scenario,$=v=>document.querySelector(v);
 if(s){const goals=scenarioGoals(c),d=scenarioDefinition(s),remaining=Math.max(0,d.months-(c.month-s.startMonth));dialog('Scenario status · '+d.title,`<p>${s.status==='playing'?`${remaining} months remain. Goals are checked at the end of each simulation month.`:s.status==='won'?`Scenario won · ${escapeAnnouncement(s.rank)}. Completed in ${s.endedMonth-s.startMonth} months.`:s.id==='roadless'?`Scenario lost: roads were present at a monthly check. Challenge month ${s.endedMonth-s.startMonth}.`:scenarioEnding(s)?`Scenario ended in loss · ${escapeAnnouncement(s.rank)}. Challenge month ${s.endedMonth-s.startMonth}.`:`Scenario lost: the ${d.months}-month deadline passed before all goals were met.`}</p>${scenarioResultMessage(s)}<p>${d.description}</p>${scenarioSpeedReport(c)}${backgroundRulesReport(c)}<ol>${goals.map((g,i)=>`<li><strong>${g.done?'✓ ':''}${escapeAnnouncement(g.title)}</strong>${g.instructions?`<p style="white-space:pre-wrap">${escapeAnnouncement(g.instructions)}</p>`:''}<br>${escapeAnnouncement(g.detail)}${g.area&&ui.viewArea?`<br><button data-goal-area="${i}">View goal area</button>`:''}</li>`).join('')}</ol>${s.id==='custom'?scenarioStory(s,c):`<p>${d.briefing}</p>`}${scenarioRanksReport(c)}${scenarioEventReport(c)}${scenarioProgramReport(c)}<div class="actions">${s.id==='custom'&&s.status==='playing'&&ui.resume?`<button id="resumeScenario">Play at ${resumeScenarioSpeed(c)}×</button>`:''}<button id="backScenario" class="primary">${s.status==='playing'?'Return to city':'Continue as sandbox'}</button>${s.id!=='custom'||s.startingCity?'<button id="retryScenario">Restart this challenge</button>':''}${s.id==='custom'?'<button id="exportCustomScenario">Export current progress</button>':''}${s.id==='custom'&&s.startingCity?'<button id="exportScenarioStart">Export playable start</button>':''}<button id="otherScenarios">Choose another challenge</button><button id="reviewScenario">Milestone 6 feedback</button></div><p class="fine">${s.id==='custom'?(s.startingCity?'Player-authored challenge. Its original starting city is saved for replay. Restart replaces current progress; export progress first to keep it.':'Older player-authored challenge without a saved starting city. Reimport its original starting file to replay it.'):d.manualAdaptation?'Adapted from the manual’s Roadless Paradise tutorial. The prepared layout and monthly check interval differ from the original.':'Original SIMS3000 challenge. Goals and timing are authored for this reconstruction, not a reproduction of a shipped SimCity scenario.'}</p>`);document.querySelectorAll('[data-event-camera]').forEach(button=>button.onclick=()=>ui.viewCamera?.(s.definition.events[Number(button.dataset.eventCamera)]));document.querySelectorAll('[data-goal-area]').forEach(button=>button.onclick=()=>ui.viewArea(goals[Number(button.dataset.goalArea)].area));if($('#resumeScenario'))$('#resumeScenario').onclick=()=>{close();ui.resume();};$('#backScenario').onclick=()=>{if(s.status!=='playing'){c.scenario=null;save();update();}close();};if(s.id==='custom')$('#exportCustomScenario').onclick=exportCity;if(s.id!=='custom')$('#retryScenario').onclick=()=>confirm(s.id);else if(s.startingCity){$('#exportScenarioStart').onclick=ui.exportStart;$('#retryScenario').onclick=()=>{dialog('Restart this challenge?',`<p>Return to the saved starting terrain, buildings, treasury and date? This replaces current progress and autosave. Export progress first to keep this attempt.</p><div class="actions"><button id="exportBeforeRetry">Export current progress</button><button id="confirmRetry" class="primary">Restart from saved start</button><button id="cancelRetry">Back</button></div>`);$('#exportBeforeRetry').onclick=exportCity;$('#confirmRetry').onclick=()=>{ui.restartCustom();close();};$('#cancelRetry').onclick=()=>showScenarios(ui);};}$('#otherScenarios').onclick=chooser;$('#reviewScenario').onclick=()=>review(6);
 }else chooser();
 function chooser(){dialog('Play a scenario',`<button id="createCustomScenario" class="primary">Create a challenge from this city</button><p>Choose a prepared city with goals and a deadline. These are original challenges using the manual’s scenario format.</p>${Object.entries(SCENARIOS).map(([id,d])=>`<div class="milestone"><small>${d.months/12} YEARS · ORIGINAL CHALLENGE</small><h3>${d.title}</h3><p>${d.description}</p><button data-scenario="${id}">View briefing</button></div>`).join('')}`);$('#createCustomScenario').onclick=()=>showCustomScenarioEditor(ui,()=>showScenarios(ui));document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>confirm(b.dataset.scenario));}
 function confirm(id){const d=SCENARIOS[id],preview=createScenario(id);dialog(d.title,`<p>${d.description}</p>${scenarioPreviewPanel(preview)}<p>${d.briefing}</p><p>Starting replaces your current city and autosave. Export the current city to keep a copy.</p><div class="actions"><button id="exportScenario">Export current city</button><button id="startScenario" class="primary">Start challenge</button><button id="cancelScenario">Back to scenarios</button></div>`);installScenarioPreview(preview);$('#exportScenario').onclick=exportCity;$('#startScenario').onclick=()=>{start(id);close();};$('#cancelScenario').onclick=chooser;}
}
